export const PHYSICAL_ASSET_BUNDLE_IDENTITY_PROJECTION_SCHEMA='refas.physical-asset-bundle-identity-projection/v1';
export const PHYSICAL_MODULE_CLOSURE_SCHEMA='refas.physical-module-closure/v1';
export const PHYSICAL_ASSET_COMPONENT_SCHEMAS=Object.freeze(['refas.rigid-body-dynamics/v1','refas.collision-model/v1','refas.articulation-graph/v1','refas.mechanism-graph/v1','refas.transmission-model/v1','refas.actuation-model/v1','refas.control-profile/v1','refas.runtime-binding/v1']);

const COMPONENT_DIGEST_FIELD=new Map([
 ['refas.rigid-body-dynamics/v1','dynamicsDigest'],['refas.collision-model/v1','collisionDigest'],['refas.articulation-graph/v1','articulationDigest'],['refas.mechanism-graph/v1','mechanismDigest'],['refas.transmission-model/v1','transmissionDigest'],['refas.actuation-model/v1','actuationDigest'],['refas.control-profile/v1','controlProfileDigest'],['refas.runtime-binding/v1','runtimeBindingDigest'],
]);
const COMPONENT_VALIDATOR=new Map([
 ['refas.rigid-body-dynamics/v1',(c)=>validateRigidBodyDynamics(c)],
 ['refas.collision-model/v1',(c)=>validateCollisionModel(c)],
 ['refas.articulation-graph/v1',(c,ctx)=>{
   if(!ctx?.attachmentSemantics||!Array.isArray(ctx?.jointContracts)||!ctx.jointContracts.length)return{valid:false,errors:['P04 articulation component validation requires validationContext.attachmentSemantics and validationContext.jointContracts']};
   return validateArticulationGraph(c,{attachmentSemantics:ctx.attachmentSemantics,jointContracts:ctx.jointContracts});
 }],
 ['refas.mechanism-graph/v1',(c)=>validateMechanismGraph(c)],['refas.transmission-model/v1',(c)=>validateTransmissionModel(c)],['refas.actuation-model/v1',(c)=>validateActuationModel(c)],['refas.control-profile/v1',(c)=>validateControlProfile(c)],['refas.runtime-binding/v1',(c)=>validateRuntimeBinding(c)],
]);
const TOP_LEVEL_KEYS=new Set(['schema','bundleId','scopeId','sourceSha256','rootModuleId','identityBinding','componentRefs','moduleClosures','rootClosureDigest','policy','bundleDigest']);
const IDENTITY_BINDING_KEYS=new Set(['schema','sourceSchema','projectionDigest']);
const COMPONENT_REF_KEYS=new Set(['componentId','ownerModuleId','schema','digest']);
const LOCAL_COMPONENT_REF_KEYS=new Set(['componentId','schema','digest']);
const MODULE_CLOSURE_KEYS=new Set(['schema','moduleId','identityProjectionDigest','componentRefs','childModules','closureDigest']);
const CHILD_MODULE_KEYS=new Set(['relationId','moduleId','placementFrame','closureDigest']);
const TRANSFORM_KEYS=new Set(['parentId','translation_m','rotation_quat_xyzw']);
const POLICY_KEYS=new Set(['bundleIsManifestNotTruthOwner','componentPayloadsRemainExternal','scopedIdentityProjection','componentCanonicalityDelegatedUpstream','componentOwnershipMustCoverSemanticReferences','rootIncomingPlacementExcludedFromModuleClosure','childPlacementOwnedByParentClosure','childClosureReusedByExactDigest','backendOrderingIsNotSemanticIdentity','bundleDoesNotAuthorizePhysicalClaims']);
const CANONICAL_POLICY=Object.freeze({bundleIsManifestNotTruthOwner:true,componentPayloadsRemainExternal:true,scopedIdentityProjection:true,componentCanonicalityDelegatedUpstream:true,componentOwnershipMustCoverSemanticReferences:true,rootIncomingPlacementExcludedFromModuleClosure:true,childPlacementOwnedByParentClosure:true,childClosureReusedByExactDigest:true,backendOrderingIsNotSemanticIdentity:true,bundleDoesNotAuthorizePhysicalClaims:true});

function assertRecord(v,l){if(!v||typeof v!=='object'||Array.isArray(v))throw new Error(`${l} must be an object`);return v;}
function assertKnownKeys(v,a,l){assertRecord(v,l);const x=Object.keys(v).filter((k)=>!a.has(k));if(x.length)throw new Error(`${l} contains unsupported field(s): ${x.sort().join(', ')}`);}
function finite(v,l){if(typeof v!=='number'||!Number.isFinite(v))throw new Error(`${l} must be a finite number`);return Object.is(v,-0)?0:v;}
function vector(v,n,l){if(!Array.isArray(v)||v.length!==n)throw new Error(`${l} must contain exactly ${n} numbers`);return v.map((x,i)=>finite(x,`${l}[${i}]`));}
function placement(raw,l){if(raw==null)return null;assertKnownKeys(raw,TRANSFORM_KEYS,l);return{parentId:assertId(raw.parentId,`${l}.parentId`),translation_m:vector(raw.translation_m,3,`${l}.translation_m`),rotation_quat_xyzw:canonicalizePhysicalQuaternion(raw.rotation_quat_xyzw,`${l}.rotation_quat_xyzw`)};}
function validateIdentityGraph(g){const v=validatePhysicalIdentityGraph(g);if(!v.valid)throw new Error(`identityGraph is invalid: ${v.errors.join('; ')}`);return g;}
function entitySnapshot(e,{stripFrame=false}={}){const r={id:e.id,kind:e.kind};if(!stripFrame&&e.frame!=null)r.frame=structuredClone(e.frame);if(e.compatibilityFamilyIds!=null)r.compatibilityFamilyIds=[...e.compatibilityFamilyIds];return r;}
function relationSnapshot(r){const o={id:r.id,kind:r.kind,sourceId:r.sourceId,targetIds:[...r.targetIds]};if(r.attachmentRelationId!=null)o.attachmentRelationId=r.attachmentRelationId;return o;}
function physicalMaps(g){const entityById=new Map(g.entities.map((e)=>[e.id,e])),containsByModule=new Map(),exposesByModule=new Map();for(const r of g.relations){if(r.kind==='CONTAINS'){if(!containsByModule.has(r.sourceId))containsByModule.set(r.sourceId,[]);containsByModule.get(r.sourceId).push(r);}if(r.kind==='EXPOSES'){if(!exposesByModule.has(r.sourceId))exposesByModule.set(r.sourceId,[]);exposesByModule.get(r.sourceId).push(r);}}for(const v of [...containsByModule.values(),...exposesByModule.values()])v.sort((a,b)=>a.id.localeCompare(b.id));return{entityById,containsByModule,exposesByModule};}
function directChildModules(moduleId,m){return(m.containsByModule.get(moduleId)??[]).flatMap((r)=>r.targetIds.map((targetId)=>({relation:r,targetId}))).filter(({targetId})=>m.entityById.get(targetId)?.kind==='assembly-module').sort((a,b)=>a.targetId.localeCompare(b.targetId));}
function moduleSubtree(g,rootModuleId){const maps=physicalMaps(g),root=maps.entityById.get(rootModuleId);if(!root)throw new Error(`rootModuleId references unknown physical identity: ${rootModuleId}`);if(root.kind!=='assembly-module')throw new Error(`rootModuleId must reference assembly-module, found ${root.kind}`);const moduleIds=new Set(),selectedIds=new Set(),stack=[rootModuleId];while(stack.length){const moduleId=stack.pop();if(moduleIds.has(moduleId))continue;moduleIds.add(moduleId);selectedIds.add(moduleId);for(const r of maps.containsByModule.get(moduleId)??[])for(const id of r.targetIds){selectedIds.add(id);if(maps.entityById.get(id)?.kind==='assembly-module')stack.push(id);}for(const r of maps.exposesByModule.get(moduleId)??[])for(const id of r.targetIds)selectedIds.add(id);}return{maps,moduleIds,selectedIds};}

export function physicalAssetBundleIdentityProjection(g,rootModuleId){validateIdentityGraph(g);const root=assertId(rootModuleId,'rootModuleId'),{maps,selectedIds}=moduleSubtree(g,root);const entities=[...selectedIds].map((id)=>maps.entityById.get(id)).filter(Boolean).map((e)=>entitySnapshot(e,{stripFrame:e.id===root})).sort((a,b)=>a.id.localeCompare(b.id));const relations=g.relations.filter((r)=>selectedIds.has(r.sourceId)&&r.targetIds.every((id)=>selectedIds.has(id))).map(relationSnapshot).sort((a,b)=>a.id.localeCompare(b.id));return deepFreeze({schema:PHYSICAL_ASSET_BUNDLE_IDENTITY_PROJECTION_SCHEMA,scopeId:g.scopeId,sourceSha256:g.sourceSha256,rootModuleId:root,entities,relations});}
function identityBindingFor(g,root){return{schema:PHYSICAL_ASSET_BUNDLE_IDENTITY_BINDING_SCHEMA,sourceSchema:'refas.physical-identity-graph/v1',projectionDigest:digestJson(physicalAssetBundleIdentityProjection(g,root))};}
function normalizeIdentityBinding(raw,l='identityBinding'){assertKnownKeys(raw,IDENTITY_BINDING_KEYS,l);if(raw.schema!==PHYSICAL_ASSET_BUNDLE_IDENTITY_BINDING_SCHEMA)throw new Error(`${l}.schema must be ${PHYSICAL_ASSET_BUNDLE_IDENTITY_BINDING_SCHEMA}`);if(raw.sourceSchema!=='refas.physical-identity-graph/v1')throw new Error(`${l}.sourceSchema must be refas.physical-identity-graph/v1`);return{schema:raw.schema,sourceSchema:raw.sourceSchema,projectionDigest:assertDigest(raw.projectionDigest,`${l}.projectionDigest`)};}

function componentSemanticIdentityIds(c){switch(c.schema){
 case'refas.rigid-body-dynamics/v1':case'refas.collision-model/v1':return(c.links??[]).map((x)=>x.linkId);
 case'refas.articulation-graph/v1':return[c.rootLinkId,...(c.linkBindings??[]).map((x)=>x.linkId),...(c.joints??[]).flatMap((x)=>[x.virtualJointId,x.parentLinkId,x.childLinkId])];
 case'refas.mechanism-graph/v1':return(c.mechanisms??[]).flatMap((m)=>[m.mechanismId,...(m.realizedJointIds??[]),...(m.members??[]).map((x)=>x.physicalIdentityId)]);
 case'refas.transmission-model/v1':return(c.transmissions??[]).flatMap((t)=>[t.transmissionId,...(t.contextMechanismIds??[]),...(t.inputSpace?.coordinates??[]).map((x)=>x.semanticIdentityId),...(t.outputSpace?.coordinates??[]).map((x)=>x.semanticIdentityId)]);
 case'refas.actuation-model/v1':return(c.actuators??[]).flatMap((a)=>[a.actuatorId,a.drivenTargetId]);
 case'refas.control-profile/v1':return(c.profiles??[]).flatMap((p)=>[p.selector?.controllerId,p.selector?.actuatorId]);
 case'refas.runtime-binding/v1':return(c.bindings??[]).flatMap((b)=>[b.selector?.runtimeEndpointId,b.selector?.targetId]);default:return[];}}
function validateComponentContract(c,l,ctx){assertRecord(c,l);const schema=String(c.schema??''),validator=COMPONENT_VALIDATOR.get(schema);if(!validator)throw new Error(`${l}.schema is not a supported P10 component schema: ${schema||'null'}`);const v=validator(c,ctx);if(!v?.valid)throw new Error(`${l} is not a canonical ${schema} contract: ${(v?.errors??['unknown validation failure']).join('; ')}`);const f=COMPONENT_DIGEST_FIELD.get(schema),digest=assertDigest(c[f],`${l}.${f}`),payload={...c};delete payload[f];if(digestJson(payload)!==digest)throw new Error(`${l}.${f} does not reproduce from the supplied component payload`);return{schema,digest};}
function validateComponentLocality(c,ownerModuleId,g,l){const ownerScope=moduleSubtree(g,ownerModuleId).selectedIds,entityById=new Map(g.entities.map((e)=>[e.id,e])),ids=[...new Set(componentSemanticIdentityIds(c).filter((id)=>id!=null))].sort();if(!ids.length)throw new Error(`${l} does not expose any P01 semantic identity references for ownership validation`);for(const id of ids){if(!entityById.has(id))throw new Error(`${l} references unknown current P01 semantic identity: ${id}`);if(!ownerScope.has(id))throw new Error(`${l} semantic identity ${id} lies outside ownerModuleId subtree ${ownerModuleId}`);}return ids;}
function normalizeLiveComponents(components,g,moduleIds){if(!Array.isArray(components))throw new Error('components must be an array');const refs=components.map((item,i)=>{const l=`components[${i}]`;assertRecord(item,l);const extras=Object.keys(item).filter((k)=>!['componentId','ownerModuleId','contract','validationContext'].includes(k));if(extras.length)throw new Error(`${l} contains unsupported field(s): ${extras.sort().join(', ')}`);const componentId=assertId(item.componentId,`${l}.componentId`),ownerModuleId=assertId(item.ownerModuleId,`${l}.ownerModuleId`);if(!moduleIds.has(ownerModuleId))throw new Error(`${l}.ownerModuleId is outside the selected root-module subtree: ${ownerModuleId}`);const{schema,digest}=validateComponentContract(item.contract,`${l}.contract`,item.validationContext??null);if(item.contract.scopeId!==g.scopeId||item.contract.sourceSha256!==g.sourceSha256)throw new Error(`${l}.contract scope/source does not match the physical identity graph`);validateComponentLocality(item.contract,ownerModuleId,g,`${l}.contract`);return{componentId,ownerModuleId,schema,digest};}).sort((a,b)=>a.componentId.localeCompare(b.componentId));if(new Set(refs.map((x)=>x.componentId)).size!==refs.length)throw new Error('componentId values must be globally unique within one physical asset bundle');return refs;}

function normalizeComponentRef(raw,l){assertKnownKeys(raw,COMPONENT_REF_KEYS,l);const schema=String(raw.schema??'');if(!COMPONENT_DIGEST_FIELD.has(schema))throw new Error(`${l}.schema is not supported by P10: ${schema||'null'}`);return{componentId:assertId(raw.componentId,`${l}.componentId`),ownerModuleId:assertId(raw.ownerModuleId,`${l}.ownerModuleId`),schema,digest:assertDigest(raw.digest,`${l}.digest`)};}
function normalizeLocalComponentRef(raw,l){assertKnownKeys(raw,LOCAL_COMPONENT_REF_KEYS,l);const schema=String(raw.schema??'');if(!COMPONENT_DIGEST_FIELD.has(schema))throw new Error(`${l}.schema is not supported by P10: ${schema||'null'}`);return{componentId:assertId(raw.componentId,`${l}.componentId`),schema,digest:assertDigest(raw.digest,`${l}.digest`)};}
function moduleIdentityProjectionDigest(g,moduleId){return digestJson(physicalAssetBundleIdentityProjection(g,moduleId));}
function buildClosures(g,rootModuleId,componentRefs){const{maps,moduleIds}=moduleSubtree(g,rootModuleId),refsByModule=new Map([...moduleIds].map((id)=>[id,[]]));for(const r of componentRefs)refsByModule.get(r.ownerModuleId).push(r);for(const rs of refsByModule.values())rs.sort((a,b)=>a.componentId.localeCompare(b.componentId));const closureByModule=new Map(),visiting=new Set();function close(moduleId){if(closureByModule.has(moduleId))return closureByModule.get(moduleId);if(visiting.has(moduleId))throw new Error(`module closure recursion contains a cycle at ${moduleId}`);visiting.add(moduleId);const childModules=directChildModules(moduleId,maps).map(({relation,targetId})=>{if(!moduleIds.has(targetId))throw new Error(`child module ${targetId} escaped selected root-module subtree`);const childClosure=close(targetId),childEntity=maps.entityById.get(targetId);return{relationId:relation.id,moduleId:targetId,placementFrame:childEntity.frame==null?null:structuredClone(childEntity.frame),closureDigest:childClosure.closureDigest};}).sort((a,b)=>a.moduleId.localeCompare(b.moduleId));const localComponentRefs=(refsByModule.get(moduleId)??[]).map((r)=>({componentId:r.componentId,schema:r.schema,digest:r.digest})),payload={schema:PHYSICAL_MODULE_CLOSURE_SCHEMA,moduleId,identityProjectionDigest:moduleIdentityProjectionDigest(g,moduleId),componentRefs:localComponentRefs,childModules},closure=deepFreeze({...payload,closureDigest:digestJson(payload)});visiting.delete(moduleId);closureByModule.set(moduleId,closure);return closure;}close(rootModuleId);return[...closureByModule.values()].sort((a,b)=>a.moduleId.localeCompare(b.moduleId));}
function normalizeChildModule(raw,l){assertKnownKeys(raw,CHILD_MODULE_KEYS,l);return{relationId:assertId(raw.relationId,`${l}.relationId`),moduleId:assertId(raw.moduleId,`${l}.moduleId`),placementFrame:placement(raw.placementFrame,`${l}.placementFrame`),closureDigest:assertDigest(raw.closureDigest,`${l}.closureDigest`)};}
function normalizeModuleClosure(raw,l){assertKnownKeys(raw,MODULE_CLOSURE_KEYS,l);if(raw.schema!==PHYSICAL_MODULE_CLOSURE_SCHEMA)throw new Error(`${l}.schema must be ${PHYSICAL_MODULE_CLOSURE_SCHEMA}`);const componentRefs=(raw.componentRefs??[]).map((x,i)=>normalizeLocalComponentRef(x,`${l}.componentRefs[${i}]`)).sort((a,b)=>a.componentId.localeCompare(b.componentId));if(new Set(componentRefs.map((x)=>x.componentId)).size!==componentRefs.length)throw new Error(`${l}.componentRefs contains duplicate componentId values`);const childModules=(raw.childModules??[]).map((x,i)=>normalizeChildModule(x,`${l}.childModules[${i}]`)).sort((a,b)=>a.moduleId.localeCompare(b.moduleId));if(new Set(childModules.map((x)=>x.moduleId)).size!==childModules.length)throw new Error(`${l}.childModules contains duplicate moduleId values`);if(new Set(childModules.map((x)=>x.relationId)).size!==childModules.length)throw new Error(`${l}.childModules contains duplicate relationId values`);const payload={schema:raw.schema,moduleId:assertId(raw.moduleId,`${l}.moduleId`),identityProjectionDigest:assertDigest(raw.identityProjectionDigest,`${l}.identityProjectionDigest`),componentRefs,childModules},closureDigest=assertDigest(raw.closureDigest,`${l}.closureDigest`);if(digestJson(payload)!==closureDigest)throw new Error(`${l}.closureDigest does not reproduce`);return{...payload,closureDigest};}
function normalizePolicy(raw){assertKnownKeys(raw,POLICY_KEYS,'policy');if(digestJson(raw)!==digestJson(CANONICAL_POLICY))throw new Error('policy must equal the canonical P10 policy');return{...CANONICAL_POLICY};}
function validateClosureReachability(rootModuleId,closureByModule){const visited=new Set(),visiting=new Set();function walk(moduleId){if(visiting.has(moduleId))throw new Error(`module closure graph contains a cycle at ${moduleId}`);if(visited.has(moduleId))return;const closure=closureByModule.get(moduleId);if(!closure)throw new Error(`module closure graph references missing module ${moduleId}`);visiting.add(moduleId);for(const child of closure.childModules)walk(child.moduleId);visiting.delete(moduleId);visited.add(moduleId);}walk(rootModuleId);if(visited.size!==closureByModule.size){const u=[...closureByModule.keys()].filter((id)=>!visited.has(id)).sort();throw new Error(`module closure graph contains unreachable module(s): ${u.join(', ')}`);}}
function normalizePersistedBundle(value){assertKnownKeys(value,TOP_LEVEL_KEYS,'physical asset bundle');if(value.schema!==PHYSICAL_ASSET_BUNDLE_SCHEMA)throw new Error(`schema must be ${PHYSICAL_ASSET_BUNDLE_SCHEMA}`);const bundleId=assertId(value.bundleId,'bundleId'),scopeId=assertId(value.scopeId,'scopeId'),sourceSha256=assertDigest(value.sourceSha256,'sourceSha256'),rootModuleId=assertId(value.rootModuleId,'rootModuleId'),identityBinding=normalizeIdentityBinding(value.identityBinding);if(!Array.isArray(value.componentRefs))throw new Error('componentRefs must be an array');const componentRefs=value.componentRefs.map((x,i)=>normalizeComponentRef(x,`componentRefs[${i}]`)).sort((a,b)=>a.componentId.localeCompare(b.componentId));if(new Set(componentRefs.map((x)=>x.componentId)).size!==componentRefs.length)throw new Error('componentRefs contains duplicate componentId values');if(!Array.isArray(value.moduleClosures)||!value.moduleClosures.length)throw new Error('moduleClosures must contain at least one module closure');const moduleClosures=value.moduleClosures.map((x,i)=>normalizeModuleClosure(x,`moduleClosures[${i}]`)).sort((a,b)=>a.moduleId.localeCompare(b.moduleId)),closureByModule=new Map(moduleClosures.map((x)=>[x.moduleId,x]));if(closureByModule.size!==moduleClosures.length)throw new Error('moduleClosures contains duplicate moduleId values');if(!closureByModule.has(rootModuleId))throw new Error('rootModuleId has no corresponding module closure');const globalRefById=new Map(componentRefs.map((x)=>[x.componentId,x])),seen=new Set(),parentCount=new Map(moduleClosures.map((x)=>[x.moduleId,0]));for(const closure of moduleClosures){for(const local of closure.componentRefs){const global=globalRefById.get(local.componentId);if(!global)throw new Error(`module ${closure.moduleId} references unknown component ${local.componentId}`);if(global.ownerModuleId!==closure.moduleId)throw new Error(`component ${local.componentId} is listed under the wrong module closure`);if(global.schema!==local.schema||global.digest!==local.digest)throw new Error(`component ${local.componentId} local ref does not match global exact digest ref`);if(seen.has(local.componentId))throw new Error(`component ${local.componentId} appears in more than one module closure`);seen.add(local.componentId);}for(const child of closure.childModules){const cc=closureByModule.get(child.moduleId);if(!cc)throw new Error(`module ${closure.moduleId} references missing child closure ${child.moduleId}`);if(child.closureDigest!==cc.closureDigest)throw new Error(`module ${closure.moduleId} child closure digest is stale for ${child.moduleId}`);parentCount.set(child.moduleId,(parentCount.get(child.moduleId)??0)+1);}}if(seen.size!==componentRefs.length)throw new Error('every global component ref must appear exactly once in its owner module closure');if((parentCount.get(rootModuleId)??0)!==0)throw new Error('root module closure may not appear as a child');for(const[moduleId,count]of parentCount)if(moduleId!==rootModuleId&&count!==1)throw new Error(`non-root module closure ${moduleId} must have exactly one parent closure`);validateClosureReachability(rootModuleId,closureByModule);const rootClosure=closureByModule.get(rootModuleId);if(identityBinding.projectionDigest!==rootClosure.identityProjectionDigest)throw new Error('identityBinding must match the root module scoped identity projection digest');const rootClosureDigest=assertDigest(value.rootClosureDigest,'rootClosureDigest');if(rootClosureDigest!==rootClosure.closureDigest)throw new Error('rootClosureDigest does not match the root module closure');const policy=normalizePolicy(value.policy),payload={schema:value.schema,bundleId,scopeId,sourceSha256,rootModuleId,identityBinding,componentRefs,moduleClosures,rootClosureDigest,policy},bundleDigest=assertDigest(value.bundleDigest,'bundleDigest');if(digestJson(payload)!==bundleDigest)throw new Error('bundleDigest does not reproduce');return{...payload,bundleDigest};}

export function createPhysicalAssetBundle({bundleId,identityGraph,rootModuleId,components=[]}={}){validateIdentityGraph(identityGraph);const normalizedBundleId=assertId(bundleId,'bundleId'),root=assertId(rootModuleId,'rootModuleId'),{moduleIds}=moduleSubtree(identityGraph,root),componentRefs=normalizeLiveComponents(components,identityGraph,moduleIds),moduleClosures=buildClosures(identityGraph,root,componentRefs),rootClosure=moduleClosures.find((x)=>x.moduleId===root),payload={schema:PHYSICAL_ASSET_BUNDLE_SCHEMA,bundleId:normalizedBundleId,scopeId:identityGraph.scopeId,sourceSha256:identityGraph.sourceSha256,rootModuleId:root,identityBinding:identityBindingFor(identityGraph,root),componentRefs,moduleClosures,rootClosureDigest:rootClosure.closureDigest,policy:{...CANONICAL_POLICY}};return deepFreeze({...payload,bundleDigest:digestJson(payload)});}
export function validatePhysicalAssetBundle(value){const errors=[];try{const normalized=normalizePersistedBundle(value);if(digestJson(normalized)!==digestJson(value))errors.push('physical asset bundle is not canonical');}catch(error){errors.push(error.message);}return{valid:errors.length===0,errors};}
export function validatePhysicalAssetBundleBindings(value,{identityGraph,components=[]}={}){const errors=[],intrinsic=validatePhysicalAssetBundle(value);if(!intrinsic.valid)errors.push(`physical asset bundle invalid: ${intrinsic.errors.join('; ')}`);try{if(!errors.length){const recreated=createPhysicalAssetBundle({bundleId:value.bundleId,identityGraph,rootModuleId:value.rootModuleId,components});if(recreated.bundleDigest!==value.bundleDigest)errors.push('physical asset bundle does not reproduce against current identity/component inputs');if(digestJson(recreated)!==digestJson(value))errors.push('physical asset bundle current bindings are stale or noncanonical');}}catch(error){errors.push(error.message);}return{valid:errors.length===0,errors};}
export function physicalModuleClosureById(bundle,moduleId){const v=validatePhysicalAssetBundle(bundle);if(!v.valid)throw new Error(`physical asset bundle is invalid: ${v.errors.join('; ')}`);const id=assertId(moduleId,'moduleId');return bundle.moduleClosures.find((x)=>x.moduleId===id)??null;}
